<?php
require dirname(__DIR__).'/vendor/autoload.php';Dotenv\Dotenv::createImmutable(dirname(__DIR__))->load();
use App\Core\Database;use App\Models\WorkoutTemplate;use App\Services\ActiveWorkoutService;
$service=new ActiveWorkoutService();if($service->active())throw new RuntimeException('An active workout already exists; workout-mode test was not run.');$template=WorkoutTemplate::forDay(7)??throw new RuntimeException('Leg workout plan is missing.');$state=$service->start((int)$template['id']);$sessionId=(int)$state['session']['id'];
try{
    if($state['current']['name']!=='Leg Press'||(int)$state['current']['target_set_count']!==4||$state['currentSet']['set_type']!=='warmup')throw new RuntimeException('Workout plan was not initialized with warm-up and working sets.');$replacement=$state['replacementCandidates'][0]??null;if($replacement){$originalExerciseId=(int)$state['current']['exercise_id'];$service->replaceExercise((int)$replacement['id']);$replaced=$service->active();if((int)$replaced['current']['exercise_id']!==(int)$replacement['id'])throw new RuntimeException('Exercise replacement was not persisted.');$service->replaceExercise($originalExerciseId);$state=$service->active();if($state['current']['name']!=='Leg Press')throw new RuntimeException('Exercise replacement could not be reversed.');}
