    $sets=0;$exerciseCompletions=0;while(($state=$service->active())&&$state['current']){$result=$service->completeSet(['weight_kg'=>$state['defaultWeight']?:50,'repetitions'=>12,'set_type'=>$state['currentSet']['set_type']??'working']);$sets++;if($sets===1&&$replacement){try{$service->replaceExercise((int)$replacement['id']);throw new RuntimeException('A replacement was allowed after completing a set.');}catch(RuntimeException $exception){if($exception->getMessage()==='A replacement was allowed after completing a set.')throw $exception;}}if($result['status']==='exercise_completed')$exerciseCompletions++;if($sets>24)throw new RuntimeException('Workout did not advance.');}
    $summary=$service->summary();if($sets!==16||count($summary['summary'])!==4||$exerciseCompletions!==3)throw new RuntimeException('Workout completion state is incorrect.');$finished=$service->finish('Automated workout-mode test');if($finished!==$sessionId)throw new RuntimeException('Workout was not finished.');echo "✓ Workout Mode: planned sets, dynamic sets, body weight, advancement and completion\n";
}finally{Database::connection()->prepare('DELETE FROM workout_sessions WHERE id=?')->execute([$sessionId]);Database::connection()->prepare("DELETE FROM body_weight_entries WHERE recorded_on=CURRENT_DATE AND source='workout'")->execute();}
